/bin/bash -lc "python3 -c \"
import numpy as np
d = np.load('source_pixels.npz')['rgb'].astype(int)
R,G,B=d[...,0],d[...,1],d[...,2]
red=(R>150)&(G<120)&(B<120)
for fi in [0,5,10,20,30,45,60,75,95]:
    ys,xs=np.where(red[fi])
    if len(xs): print(f'f{fi}: red bbox x {xs.min()}-{xs.max()} y {ys.min()}-{ys.max()} n={red[fi].sum()} cx={xs.mean():.1f} cy={ys.mean():.1f}')
    else: print(f'f{fi}: no red')
\""
